  reserve=read(D/'geometry-audit.json');tyre=base147['Samples'][1000]['Forces']['TyreLoads'];capacity=tyre['TotalCapacityNewtons'];radius=reserve['MinimumReferenceRadius'];bounds=dict(capacity_N=capacity,mass_kg=147,minimum_reference_radius_m=radius,optimistic_outer_constant_offset_radius_m=radius+15.6,optimistic_constant_offset_kph=3.6*math.sqrt(capacity/147*(radius+15.6)),steady_radius_required_at90_m=147*25**2/capacity,scope='pointwise optimistic constant-offset steady-state bound; not an optimum or a bound over every varying-offset path')
